-- One-off: move company and lead areas to Vietnam's map after the 2025
-- merger (in force 2025-07-01): 34 provinces/cities and their wards, communes
-- and special zones; the district tier no longer exists (owner decision
-- 2026-11-02). Source: General Statistics Office list (QĐ 19/2025/QĐ-TTg),
-- the same list as src/data/vn-admin-units.json; pre-merger provinces follow
-- Nghị quyết 202/2025/QH15.
--
-- city: every spelling of a current or pre-merger province becomes the
--   current official name; anything else becomes ''.
-- ward: kept only when it is the official name of a ward of that province;
--   pre-merger wards ("Phường 13") become '' rather than being guessed.
-- district: ''. Changed rows get a new version; one audit row records counts
-- (only when there was anything to move).
-- Columns are unchanged (additive schema); the two lookup tables are dropped.
CREATE TABLE tmp_area_city_map (spelling TEXT PRIMARY KEY, city TEXT NOT NULL);
CREATE TABLE tmp_area_wards (city TEXT NOT NULL, ward TEXT NOT NULL, PRIMARY KEY (city, ward));
