CREATE TABLE tmp_area_crm_accounts AS SELECT id,
    COALESCE((SELECT m.city FROM tmp_area_city_map m WHERE m.spelling = trim(t.city)), '') AS new_city,
    ward AS old_ward FROM crm_accounts t WHERE t.city != '' OR t.ward != '' OR t.district != '';
CREATE TABLE tmp_area_crm_lead_records AS SELECT id,
    COALESCE((SELECT m.city FROM tmp_area_city_map m WHERE m.spelling = trim(t.city)), '') AS new_city,
    ward AS old_ward FROM crm_lead_records t WHERE t.city != '' OR t.ward != '' OR t.district != '';
INSERT INTO workspace_audit (id, actor_id, actor_name, action, target_user_id, detail, created_at, module, outcome, via)
SELECT 'aud_migration_0058_crm_area', 'system:migration-0058', 'Migration 0058', 'crm_area_post_merger', 'system',
  json_object(
    'accounts', (SELECT COUNT(*) FROM tmp_area_crm_accounts),
    'accounts_city_kept', (SELECT COUNT(*) FROM tmp_area_crm_accounts WHERE new_city != ''),
    'accounts_ward_kept', (SELECT COUNT(*) FROM tmp_area_crm_accounts x WHERE EXISTS (SELECT 1 FROM tmp_area_wards w WHERE w.city = x.new_city AND w.ward = x.old_ward)),
    'leads', (SELECT COUNT(*) FROM tmp_area_crm_lead_records),
    'leads_city_kept', (SELECT COUNT(*) FROM tmp_area_crm_lead_records WHERE new_city != ''),
    'leads_ward_kept', (SELECT COUNT(*) FROM tmp_area_crm_lead_records x WHERE EXISTS (SELECT 1 FROM tmp_area_wards w WHERE w.city = x.new_city AND w.ward = x.old_ward))),
  strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 'crm', 'success', 'system'
WHERE (SELECT COUNT(*) FROM tmp_area_crm_accounts) + (SELECT COUNT(*) FROM tmp_area_crm_lead_records) > 0;
UPDATE crm_accounts SET
  city = (SELECT x.new_city FROM tmp_area_crm_accounts x WHERE x.id = crm_accounts.id),
  ward = CASE WHEN EXISTS (SELECT 1 FROM tmp_area_crm_accounts x JOIN tmp_area_wards w ON w.city = x.new_city AND w.ward = x.old_ward WHERE x.id = crm_accounts.id) THEN ward ELSE '' END,
  district = '',
  version = version + 1,
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id IN (SELECT id FROM tmp_area_crm_accounts);
UPDATE crm_lead_records SET
  city = (SELECT x.new_city FROM tmp_area_crm_lead_records x WHERE x.id = crm_lead_records.id),
  ward = CASE WHEN EXISTS (SELECT 1 FROM tmp_area_crm_lead_records x JOIN tmp_area_wards w ON w.city = x.new_city AND w.ward = x.old_ward WHERE x.id = crm_lead_records.id) THEN ward ELSE '' END,
  district = '',
  version = version + 1,
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id IN (SELECT id FROM tmp_area_crm_lead_records);
DROP TABLE tmp_area_crm_accounts;
DROP TABLE tmp_area_crm_lead_records;
DROP TABLE tmp_area_wards;
DROP TABLE tmp_area_city_map;
